;=concatenate(&amp;quot;The base wage range for this position based in our New York City Office is targeted at &amp;quot;,TEXT(R[0]C[-2],&amp;quot;$#,##0.00&amp;quot;),&amp;quot; to &amp;quot;,TEXT(R[0]C[-1],&amp;quot;$#,##0.00&amp;quot;), &amp;quot; per &amp;quot;,(if(R[0]C[-4]=&amp;quot;Exempt&amp;quot;,&amp;quot;year.&amp;quot;,&amp;quot;hour.&amp;quot;)))&quot;&gt;#LI-SP1&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Actual compensation is based on multiple factors that are unique to each candidate, including and not limited to skill set, level of relevant experience, and specific work location.&amp;nbsp; &lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Salary ranges for positions based in other locations may differ based on the cost of labor in that location.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
